'use strict';

/**
 * Minimal, dependency-free PDF writer for letters and reports generated by the
 * CRM (offer letters, notices, statements, sample documents). A4 pages with a
 * letterhead, headings, wrapped paragraphs, bullet lists, two-or-more-column
 * tables and "Page n of N" footers, in the standard Helvetica fonts
 * (WinAnsi encoding — covers English and French text).
 *
 *   renderPdf({ title, letterhead: { name, subtitle }, footer, blocks })
 *   htmlToBlocks(html)          — the simple HTML our merge templates use
 *   htmlToPdf(html, options)    — both together
 *
 * Blocks: { type: 'h1'|'h2'|'p'|'bullet'|'table'|'spacer'|'rule', text, rows, align, bold, size }
 */

const A4 = { w: 595.28, h: 841.89 };
const M = { left: 56, right: 56, top: 64, bottom: 64 };

// Helvetica / Helvetica-Bold advance widths (1/1000 em) for ASCII 32–126.
const W_REG = [278, 278, 355, 556, 556, 889, 667, 191, 333, 333, 389, 584, 278, 333, 278, 278, 556, 556, 556, 556, 556, 556, 556, 556, 556, 556, 278, 278, 584, 584, 584, 556, 1015, 667, 667, 722, 722, 667, 611, 778, 722, 278, 500, 667, 556, 833, 722, 778, 667, 778, 722, 667, 611, 722, 667, 944, 667, 667, 611, 278, 278, 278, 469, 556, 333, 556, 556, 500, 556, 556, 278, 556, 556, 222, 222, 500, 222, 833, 556, 556, 556, 556, 333, 500, 278, 556, 500, 722, 500, 500, 500, 334, 260, 334, 584];
const W_BOLD = [278, 333, 474, 556, 556, 889, 722, 238, 333, 333, 389, 584, 278, 333, 278, 278, 556, 556, 556, 556, 556, 556, 556, 556, 556, 556, 333, 333, 584, 584, 584, 611, 975, 722, 722, 722, 722, 667, 611, 778, 722, 278, 556, 722, 611, 833, 722, 778, 667, 778, 722, 667, 611, 722, 667, 944, 667, 667, 611, 333, 278, 333, 584, 556, 333, 556, 611, 556, 611, 556, 333, 611, 611, 278, 278, 556, 278, 889, 611, 611, 611, 611, 389, 556, 333, 611, 556, 778, 556, 556, 500, 389, 280, 389, 584];

// Unicode → WinAnsi (cp1252) for the characters outside Latin-1 that letters use.
const CP1252 = { '€': 0x80, '‚': 0x82, '„': 0x84, '…': 0x85, '•': 0x95, '–': 0x96, '—': 0x97, '‘': 0x91, '’': 0x92, '“': 0x93, '”': 0x94, '™': 0x99, 'Œ': 0x8c, 'œ': 0x9c, 'Š': 0x8a, 'š': 0x9a, 'Ÿ': 0x9f, 'Ž': 0x8e, 'ž': 0x9e };
const SUBST = { '→': '->', '←': '<-', '≥': '>=', '≤': '<=', '≈': '~', '✓': 'v', '✔': 'v', '×': 'x', '−': '-', ' ': ' ', ' ': ' ', ' ': ' ' };

function toWinAnsi(str) {
  const out = [];
  for (const ch of String(str ?? '')) {
    const s = SUBST[ch];
    if (s !== undefined) { for (const c of s) out.push(c.charCodeAt(0)); continue; }
    const code = ch.codePointAt(0);
    if (CP1252[ch] !== undefined) out.push(CP1252[ch]);
    else if (code < 0x80 || (code >= 0xa0 && code <= 0xff)) out.push(code);
    else out.push(0x3f); // '?'
  }
  return Buffer.from(out);
}

/** Width of a string in points. Accented letters use their base letter's width. */
function textWidth(str, size, bold = false) {
  const table = bold ? W_BOLD : W_REG;
  let w = 0;
  for (const b of toWinAnsi(str)) {
    // Outside ASCII: accented capitals ≈ 'A', everything else ≈ 'a'.
    const base = b >= 32 && b <= 126 ? b : (b >= 0xc0 && b <= 0xde ? 65 : 97);
    w += table[base - 32];
  }
  return (w * size) / 1000;
}

function wrap(text, width, size, bold) {
  const lines = [];
  for (const para of String(text ?? '').split('\n')) {
    const words = para.split(/\s+/).filter(Boolean);
    if (!words.length) { lines.push(''); continue; }
    let line = '';
    for (const word of words) {
      const next = line ? `${line} ${word}` : word;
      if (textWidth(next, size, bold) <= width || !line) {
        if (!line && textWidth(word, size, bold) > width) {
          // A single word longer than the line: hard-split it.
          let chunk = '';
          for (const ch of word) {
            if (textWidth(chunk + ch, size, bold) > width) { lines.push(chunk); chunk = ''; }
            chunk += ch;
          }
          line = chunk;
        } else line = next;
      } else { lines.push(line); line = word; }
    }
    lines.push(line);
  }
  return lines;
}

const esc = (buf) => {
  let s = '';
  for (const b of buf) {
    if (b === 0x28 || b === 0x29 || b === 0x5c) s += `\\${String.fromCharCode(b)}`;
    else if (b < 32 || b > 126) s += `\\${b.toString(8).padStart(3, '0')}`;
    else s += String.fromCharCode(b);
  }
  return s;
};
const num = (n) => (Math.round(n * 100) / 100).toString();

/** Lay out blocks into page content streams. */
function layout({ letterhead, footer, blocks }) {
  const width = A4.w - M.left - M.right;
  const pages = [];
  let ops = [];
  let y = 0;

  const text = (str, x, yy, size, bold = false, grey = false) => {
    ops.push(`${grey ? '0.4 0.4 0.4 rg' : '0.1 0.1 0.12 rg'} BT /${bold ? 'F2' : 'F1'} ${num(size)} Tf ${num(x)} ${num(yy)} Td (${esc(toWinAnsi(str))}) Tj ET`);
  };
  const line = (x1, y1, x2, y2, grey = 0.75, wdt = 0.6) => ops.push(`${grey} ${grey} ${grey} RG ${wdt} w ${num(x1)} ${num(y1)} m ${num(x2)} ${num(y2)} l S`);
  const newPage = () => {
    if (ops.length) pages.push(ops);
    ops = [];
    y = A4.h - M.top;
    if (letterhead?.name) {
      text(letterhead.name, M.left, y, 15, true);
      if (letterhead.subtitle) text(letterhead.subtitle, M.left, y - 14, 8.5, false, true);
      if (letterhead.right) text(letterhead.right, A4.w - M.right - textWidth(letterhead.right, 8.5), y, 8.5, false, true);
      y -= letterhead.subtitle ? 24 : 12;
      line(M.left, y, A4.w - M.right, y, 0.35, 1.2);
      y -= 22;
    }
  };
  const need = (h) => { if (y - h < M.bottom + 20) newPage(); };

  newPage();
  for (const b of blocks) {
    if (b.type === 'spacer') { y -= b.size ?? 8; continue; }
    if (b.type === 'rule') { need(10); line(M.left, y + 4, A4.w - M.right, y + 4); y -= 10; continue; }
    if (b.type === 'table') {
      const cols = Math.max(...b.rows.map((r) => r.length));
      const widths = b.widths ?? (cols === 2 ? [width * 0.32, width * 0.68] : Array(cols).fill(width / cols));
      const size = b.size ?? 9.5;
      const lh = size * 1.35;
      if (b.header) {
        need(lh + 6);
        let x = M.left;
        b.header.forEach((h, i) => { text(h, x + 4, y - size, size, true); x += widths[i]; });
        y -= lh + 4;
        line(M.left, y + 2, A4.w - M.right, y + 2, 0.5, 0.8);
      }
      for (const row of b.rows) {
        const cells = row.map((c, i) => wrap(c, widths[i] - 8, size, i === 0 && cols === 2));
        const h = Math.max(...cells.map((c) => c.length)) * lh + 6;
        need(h);
        let x = M.left;
        cells.forEach((lines, i) => {
          lines.forEach((l, k) => text(l, x + 4, y - size - k * lh, size, i === 0 && cols === 2));
          x += widths[i];
        });
        y -= h;
        line(M.left, y + 2, A4.w - M.right, y + 2, 0.85, 0.4);
      }
      y -= 8;
      continue;
    }
    const size = b.size ?? (b.type === 'h1' ? 16 : b.type === 'h2' ? 12.5 : 10);
    const bold = b.bold ?? (b.type === 'h1' || b.type === 'h2');
    const indent = b.type === 'bullet' ? 14 : 0;
    const lines = wrap(b.text, width - indent, size, bold);
    const lh = size * 1.4;
    if (b.type === 'h1' || b.type === 'h2') { need(lh * Math.min(lines.length, 2) + 30); y -= 4; }
    for (const [i, l] of lines.entries()) {
      need(lh);
      let x = M.left + indent;
      if (b.align === 'right') x = A4.w - M.right - textWidth(l, size, bold);
      else if (b.align === 'center') x = M.left + (width - textWidth(l, size, bold)) / 2;
      if (b.type === 'bullet' && i === 0) text('•', M.left + 3, y - size, size);
      text(l, x, y - size, size, bold, b.grey);
      y -= lh;
    }
    y -= b.type === 'h1' ? 8 : b.type === 'h2' ? 4 : 6;
  }
  pages.push(ops);

  // Footers once the page count is known.
  return pages.map((p, i) => {
    const f = [];
    const label = `Page ${i + 1} of ${pages.length}`;
    f.push(`0.75 0.75 0.75 RG 0.5 w ${M.left} ${M.bottom - 6} m ${num(A4.w - M.right)} ${M.bottom - 6} l S`);
    if (footer) f.push(`0.45 0.45 0.45 rg BT /F1 7.5 Tf ${M.left} ${M.bottom - 18} Td (${esc(toWinAnsi(footer))}) Tj ET`);
    f.push(`0.45 0.45 0.45 rg BT /F1 7.5 Tf ${num(A4.w - M.right - textWidth(label, 7.5))} ${M.bottom - 18} Td (${esc(toWinAnsi(label))}) Tj ET`);
    return [...p, ...f].join('\n');
  });
}

/** Render blocks to a PDF Buffer. */
function renderPdf({ title = 'Document', author = 'Genesis CRM', letterhead = null, footer = null, blocks = [] } = {}) {
  const streams = layout({ letterhead, footer, blocks });
  const objs = [];
  const add = (body) => { objs.push(body); return objs.length; };
  const catalog = add(null);
  const pagesId = add(null);
  const f1 = add('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>');
  const f2 = add('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>');
  const kids = [];
  for (const s of streams) {
    const content = Buffer.from(s, 'latin1');
    const c = add(Buffer.concat([Buffer.from(`<< /Length ${content.length} >>\nstream\n`, 'latin1'), content, Buffer.from('\nendstream', 'latin1')]));
    kids.push(add(`<< /Type /Page /Parent ${pagesId} 0 R /MediaBox [0 0 ${A4.w} ${A4.h}] /Resources << /Font << /F1 ${f1} 0 R /F2 ${f2} 0 R >> >> /Contents ${c} 0 R >>`));
  }
  objs[catalog - 1] = `<< /Type /Catalog /Pages ${pagesId} 0 R >>`;
  objs[pagesId - 1] = `<< /Type /Pages /Kids [${kids.map((k) => `${k} 0 R`).join(' ')}] /Count ${kids.length} >>`;
  const info = add(`<< /Title (${esc(toWinAnsi(title))}) /Author (${esc(toWinAnsi(author))}) /Producer (Genesis CRM) /CreationDate (D:${new Date().toISOString().replace(/[-:T]/g, '').slice(0, 14)}Z) >>`);

  const parts = [Buffer.from('%PDF-1.4\n%\xe2\xe3\xcf\xd3\n', 'latin1')];
  const offsets = [];
  let pos = parts[0].length;
  objs.forEach((body, i) => {
    const head = Buffer.from(`${i + 1} 0 obj\n`, 'latin1');
    const b = Buffer.isBuffer(body) ? body : Buffer.from(body, 'latin1');
    const tail = Buffer.from('\nendobj\n', 'latin1');
    offsets.push(pos);
    parts.push(head, b, tail);
    pos += head.length + b.length + tail.length;
  });
  const xref = [`xref\n0 ${objs.length + 1}\n0000000000 65535 f \n`, ...offsets.map((o) => `${String(o).padStart(10, '0')} 00000 n \n`)].join('');
  parts.push(Buffer.from(`${xref}trailer\n<< /Size ${objs.length + 1} /Root ${catalog} 0 R /Info ${info} 0 R >>\nstartxref\n${pos}\n%%EOF\n`, 'latin1'));
  return Buffer.concat(parts);
}

// ── Simple HTML → blocks ─────────────────────────────────────────────────────

const ENT = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', eacute: 'é', egrave: 'è', agrave: 'à', ccedil: 'ç', rsquo: '’', lsquo: '‘', mdash: '—', ndash: '–', euro: '€', hellip: '…' };
const decode = (s) => s.replace(/&(#x?[0-9a-f]+|[a-z]+);/gi, (m, e) => {
  if (e[0] === '#') return String.fromCodePoint(e[1] === 'x' || e[1] === 'X' ? parseInt(e.slice(2), 16) : parseInt(e.slice(1), 10));
  return ENT[e.toLowerCase()] ?? m;
});
const inline = (s) => decode(String(s).replace(/<br\s*\/?>/gi, '\n').replace(/<[^>]+>/g, '')).replace(/[ \t]+/g, ' ').replace(/ *\n */g, '\n').trim();

function htmlToBlocks(html) {
  const blocks = [];
  const src = String(html ?? '').replace(/\r/g, '').replace(/<!--[\s\S]*?-->/g, '');
  const re = /<(h1|h2|h3|p|li|table|hr)\b([^>]*)>([\s\S]*?)<\/\1>|<hr\s*\/?>/gi;
  let m;
  let last = 0;
  const loose = (chunk) => { const t = inline(chunk); if (t) blocks.push({ type: 'p', text: t }); };
  while ((m = re.exec(src))) {
    loose(src.slice(last, m.index).replace(/<\/?(div|ul|ol|body|html|section)[^>]*>/gi, ''));
    last = re.lastIndex;
    const tag = (m[1] || 'hr').toLowerCase();
    const attrs = m[2] ?? '';
    const body = m[3] ?? '';
    if (tag === 'hr') { blocks.push({ type: 'rule' }); continue; }
    if (tag === 'table') {
      const rows = [];
      let header = null;
      for (const r of body.match(/<tr\b[\s\S]*?<\/tr>/gi) ?? []) {
        const ths = [...r.matchAll(/<th\b[^>]*>([\s\S]*?)<\/th>/gi)].map((c) => inline(c[1]));
        const tds = [...r.matchAll(/<td\b[^>]*>([\s\S]*?)<\/td>/gi)].map((c) => inline(c[1]));
        if (ths.length && !tds.length) header = ths; else rows.push(tds.length ? tds : ths);
      }
      if (rows.length) blocks.push({ type: 'table', rows, header });
      continue;
    }
    const text = inline(body);
    if (!text) continue;
    const align = /text-align\s*:\s*right/i.test(attrs) ? 'right' : /text-align\s*:\s*center/i.test(attrs) ? 'center' : undefined;
    if (tag === 'h1') blocks.push({ type: 'h1', text });
    else if (tag === 'h2' || tag === 'h3') blocks.push({ type: 'h2', text });
    else if (tag === 'li') blocks.push({ type: 'bullet', text });
    else blocks.push({ type: 'p', text, align, bold: /^<(strong|b)>[\s\S]*<\/(strong|b)>$/i.test(body.trim()) || undefined });
  }
  loose(src.slice(last).replace(/<\/?(div|ul|ol|body|html|section)[^>]*>/gi, ''));
  return blocks;
}

const htmlToPdf = (html, options = {}) => renderPdf({ ...options, blocks: htmlToBlocks(html) });

module.exports = { renderPdf, htmlToBlocks, htmlToPdf, textWidth, toWinAnsi };
